[[package]]
name = "watchdog"

class ChunkedReceive:
    def __init__(self, chunks: tuple[bytes, ...]) -> None:
        self.chunks = chunks
        self.index = 0

    async def __call__(self) -> Message:
        if self.index >= len(self.chunks):
            raise AssertionError("The benchmark app read beyond the request body")
        chunk = self.chunks[self.index]
        self.index += 1
        return {
            "type": "http.request",
            "body": chunk,
            "more_body": self.index < len(self.chunks),
        }

def __init__(self, chunks: tuple[bytes, ...]) -> None:
    self.chunks = chunks
    self.index = 0

async def __call__(self) -> Message:
    if self.index >= len(self.chunks):
        raise AssertionError("The benchmark app read beyond the request body")
    chunk = self.chunks[self.index]
    self.index += 1
    return {
        "type": "http.request",
        "body": chunk,
        "more_body": self.index < len(self.chunks),
    }

class ASGIRunner:
    def __init__(self) -> None:
        self.loop = asyncio.new_event_loop()

    def run(self, app: ASGIApp, scope: Scope, receive: Receive = unreadable_receive) -> list[Message]:
        return self.loop.run_until_complete(run_asgi(app, scope, receive))

    def close(self) -> None:
        self.loop.run_until_complete(self.loop.shutdown_asyncgens())
        self.loop.close()

def close(self) -> None:
    self.loop.run_until_complete(self.loop.shutdown_asyncgens())
    self.loop.close()

class FileApp:
    def __init__(self, path: Path) -> None:
        self.path = path

    async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
        await FileResponse(self.path, media_type="application/octet-stream")(scope, receive, send)

def warm_file_response(asgi_runner: ASGIRunner, tmp_path_factory: pytest.TempPathFactory) -> None:
    path = tmp_path_factory.mktemp("file-response-warm") / "file.bin"
    path.write_bytes(b"x" * KiB)
    app = FileApp(path)
    cases = (
        BenchmarkCase("warm-fallback", KiB),
        BenchmarkCase("warm-pathsend", KiB, pathsend=True),
        BenchmarkCase("warm-range", KiB, range_header=b"bytes=0-0", expected_size=1),
    )
    for case in cases:
        for _ in range(100):
            dispatch(asgi_runner, app, case)

class BenchmarkCase:
    payload_kind: PayloadKind
    size: int
    level: int

    @property
    def id(self) -> str:
        size = f"{self.size // MiB}MiB" if self.size >= MiB else f"{self.size // KiB}KiB"
        return f"{self.payload_kind}-{size}-level-{self.level}"

def id(self) -> str:
    size = f"{self.size // MiB}MiB" if self.size >= MiB else f"{self.size // KiB}KiB"
    return f"{self.payload_kind}-{size}-level-{self.level}"

class BypassCase:
